# feature_builder.py
# PRODUCTION — ML Feature Engineering
# FIX: graceful column checks; safe scaler; explicit feature list

import numpy as np
import pandas as pd
from sklearn.preprocessing import StandardScaler

from logger_setup import get_logger

log = get_logger("feature_builder")

# Columns generated by ta_engine that must NOT be in the feature matrix
_TA_DROP = [
    "timestamp", "open", "high", "low", "future_close",
    # raw TA outputs consumed/replaced by derived features below
    "prev_high_20", "prev_low_20", "true_range",
    "trend_ma_diff",
]

_TARGET_COLS = ["target_up", "target_down", "target_breakout"]


class FeatureBuilder:
    def __init__(self):
        self.scaler: StandardScaler | None = None
        self.feature_columns: list[str] | None = None

    # ------------------------------------------------------------------
    # PUBLIC — build_features
    # ------------------------------------------------------------------
    def build_features(self, df_ta: pd.DataFrame) -> pd.DataFrame:
        """
        Receives a TA-enriched OHLCV DataFrame.
        Returns a scaled feature DataFrame.
        In training mode the DataFrame also contains target_* columns (unscaled).
        """
        if df_ta.empty or len(df_ta) < 50:
            log.warning("Insufficient rows for feature building (%d)", len(df_ta))
            return pd.DataFrame()

        df = df_ta.copy()

        # ---- 1. PRICE RATIOS -------------------------------------------
        df["close_over_open"] = df["close"] / (df["open"].replace(0, np.nan) + 1e-9)
        df["high_over_low"]   = df["high"]  / (df["low"].replace(0,  np.nan) + 1e-9)
        df["body_ratio"]      = df["body"]  / (df["range"] + 1e-9)

        # ---- 2. MOMENTUM NORMALISED ------------------------------------
        for w in [3, 7, 14]:
            col = f"momentum_{w}"
            if col in df.columns:
                df[f"momentum_{w}_norm"] = df[col] / (df["close"] + 1e-9)

        df["roll_return_3"]  = df["close"].pct_change(3).fillna(0)
        df["roll_return_7"]  = df["close"].pct_change(7).fillna(0)
        df["roll_return_14"] = df["close"].pct_change(14).fillna(0)

        # ---- 3. VOLATILITY FEATURES ------------------------------------
        df["vol_ratio"]      = df["volatility_10"] / (df["volatility_20"] + 1e-9)
        df["atr_ratio"]      = df["atr"]            / (df["close"] + 1e-9)
        df["bb_width_ratio"] = df["bb_width"]       / (df["close"] + 1e-9)

        # ---- 4. MA CROSSOVER RATIOS ------------------------------------
        df["ema10_over_ema20"] = df["ema_10"] / (df["ema_20"] + 1e-9)
        df["ema10_over_sma20"] = df["ema_10"] / (df["sma_20"] + 1e-9)
        df["close_over_sma20"] = df["close"]  / (df["sma_20"] + 1e-9)
        df["close_over_sma50"] = df["close"]  / (df["sma_50"] + 1e-9)
        df["trend_slope_5"]    = df["close"].diff(5).fillna(0)
        df["trend_slope_10"]   = df["close"].diff(10).fillna(0)

        # ---- 5. BREAKOUT / REGIME --------------------------------------
        df["breakout_signal"] = df["breakout_up"] - df["breakout_down"]
        df["regime_trend"]    = df["trend_regime"]
        df["regime_reversal"] = df["reversal_signal"]

        # ---- 6. VOLUME / LIQUIDITY -------------------------------------
        df["vol_over_vma10"]    = df["volume"] / (df["volume_ma_10"] + 1e-9)
        df["vol_over_vma20"]    = df["volume"] / (df["volume_ma_20"] + 1e-9)
        df["volatility_vol_corr"] = df["volatility_10"] * df["vol_over_vma10"]

        # ---- 7. CANDLE SHAPE -------------------------------------------
        df["upper_shadow_ratio"] = df["upper_shadow"] / (df["range"] + 1e-9)
        df["lower_shadow_ratio"] = df["lower_shadow"] / (df["range"] + 1e-9)

        # ---- 8. TARGETS (training only) --------------------------------
        df["future_close"]    = df["close"].shift(-1)
        df["future_return"]   = (df["future_close"] - df["close"]) / (df["close"] + 1e-9)
        df["target_up"]       = (df["future_return"] >  0.004).astype(int)
        df["target_down"]     = (df["future_return"] < -0.004).astype(int)
        df["target_breakout"] = df["breakout_up"].shift(-1).fillna(0).astype(int)

        # ---- 9. DROP NON-FEATURE COLUMNS -------------------------------
        drop = [c for c in _TA_DROP if c in df.columns]
        df   = df.drop(columns=drop)

        feature_cols = [c for c in df.columns if c not in _TARGET_COLS]
        self.feature_columns = feature_cols

        # ---- 10. SCALE -------------------------------------------------
        features = df[feature_cols].replace([np.inf, -np.inf], 0).fillna(0)
        scaled   = self._transform(features)

        # Re-attach targets (unscaled)
        for t in _TARGET_COLS:
            if t in df.columns:
                scaled[t] = df[t].values

        return scaled

    # ------------------------------------------------------------------
    # SCALER HELPERS
    # ------------------------------------------------------------------
    def _transform(self, df: pd.DataFrame) -> pd.DataFrame:
        if self.scaler is None:
            self.scaler = StandardScaler()
            self.scaler.fit(df)
        arr = self.scaler.transform(df)
        return pd.DataFrame(arr, columns=df.columns, index=df.index)

    def fit_transform(self, df: pd.DataFrame) -> pd.DataFrame:
        """Force re-fit the scaler (call during initial training)."""
        self.scaler = StandardScaler()
        arr = self.scaler.fit_transform(df.replace([np.inf, -np.inf], 0).fillna(0))
        return pd.DataFrame(arr, columns=df.columns, index=df.index)
